public class Bentuk {
    public double luas() {
        return 0.0;
    }
}

contoh.Persegi.java:
// Persegi.java
public class Persegi extends Bentuk {
    private double sisi;

    public Persegi(double sisi) {
        this.sisi = sisi;
    }

    @Override
    public double luas() {
        return sisi * sisi;
    }
}

contoh.Lingkaran.java:
// Lingkaran.java
public class Lingkaran extends Bentuk {
    private double jariJari;

    public Lingkaran(double jariJari) {
        this.jariJari = jariJari;
    }

    @Override
    public double luas() {
        return 3.14 * jariJari * jariJari;
    }
}

contoh.Geometri.java:
// Geometri.java
public class Geometri {
    public static double totalLuas(Bentuk[] daftar) {
        double total = 0;
        for (Bentuk b : daftar) {
            total += b.luas();
        }
        return total;
    }
}

kasus.kode:
Bentuk[] daftar = { new Persegi(2), new Lingkaran(1), new Persegi(3) };
double total = Geometri.totalLuas(daftar);
cek(Math.abs(total - 16.14) < 0.001, "total harus 16.14, hasilnya " + total);

